/* @autogenerated */
import { Injectable, inject } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { EMPTY, Observable, catchError, map, mergeMap, throwError } from 'rxjs';
import { EditConflictDialogComponent, EditConflictDialogData } from './edit-conflict-dialog.component';
import { ConflictField, EditConflict, isEditConflict } from './edit-conflict.model';

export interface SaveResolvingConflicts<T> {
  value: T;
  /** Valor cargado al empezar a editar. */
  original: T;
  fields: ConflictField[];
  /** Guarda `value`; debe emitir `EditConflictError` ante un 412 (`repository.update(value, { original })`). */
  save: (value: T, original: T) => Observable<T>;
  /** El usuario ha aplicado la fusión: rellenar el formulario con `merged` antes de reintentar. */
  merged?: (merged: T, current: T) => void;
}

/**
 * Resolución de conflictos de edición (412 por bloqueo optimista).
 *
 * @example
 * this.conflicts
 *   .save({ value, original, fields, save: (v, o) => this.repository.update(v, { original: o }) })
 *   .subscribe(() => this.close());
 */
@Injectable({ providedIn: 'root' })
export class EditConflictService {
  private readonly dialog = inject(MatDialog);

  /** Abre el diálogo de resolución; emite el valor fusionado (con la `version` actual) o `null` si se cancela. */
  resolve<T>(conflict: EditConflict<T>, fields: ConflictField[]): Observable<T | null> {
    const data: EditConflictDialogData<T> = { conflict, fields };
    return this.dialog
      .open<EditConflictDialogComponent<T>, EditConflictDialogData<T>, T | null>(EditConflictDialogComponent, {
        data,
        disableClose: true,
        width: '960px',
        maxWidth: '95vw',
        ariaLabelledBy: 'edit-conflict-title',
      })
      .afterClosed()
      .pipe(map((result) => result ?? null));
  }

  /**
   * Guarda y, ante un conflicto, abre el diálogo: si el usuario aplica, reintenta con el valor fusionado (un nuevo
   * 412 repite el ciclo); si cancela, completa sin emitir. El resto de errores se propaga.
   */
  save<T>(request: SaveResolvingConflicts<T>): Observable<T> {
    return request.save(request.value, request.original).pipe(
      catchError((error) => {
        if (!isEditConflict<T>(error)) {
          return throwError(() => error);
        }
        const conflict = error.conflict;
        return this.resolve(conflict, request.fields).pipe(
          mergeMap((merged) => {
            if (merged === null) {
              return EMPTY;
            }
            request.merged?.(merged, conflict.current);
            return this.save({ ...request, value: merged, original: conflict.current });
          }),
        );
      }),
    );
  }
}
